import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.7w-lhQN6.js";const k=JSON.parse('{"title":"Codex","description":"","frontmatter":{},"headers":[],"relativePath":"guide/codex.md","filePath":"guide/codex.md","lastUpdated":1793550481000}'),n={name:"guide/codex.md"};function o(l,e,h,d,r,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="codex" tabindex="-1">Codex <a class="header-anchor" href="#codex" aria-label="Permalink to &quot;Codex&quot;">​</a></h1><p>By the end of this page Codex has the MCP Lens plugin installed and its hooks trusted, so every MCP tool call in your Codex sessions is recorded locally and the <code>calls</code> column in <code>mcp-lens report</code> stops sitting at zero for servers you use through Codex.</p><h2 id="the-easy-way-let-the-extension-do-it" tabindex="-1">The easy way: let the extension do it <a class="header-anchor" href="#the-easy-way-let-the-extension-do-it" aria-label="Permalink to &quot;The easy way: let the extension do it&quot;">​</a></h2><p>If you use the VS Code extension, run its <code>MCP Lens: Install Hooks for All Clients</code> command and it installs this plugin for you. See <a href="/MCPLens/guide/vscode-extension">VS Code Extension</a>. If you took that route, skip the manual install section below and continue at <a href="#after-installing">After installing</a>. Do not skip it: Codex will not run the hooks until you trust their hash there, no matter how the plugin was installed.</p><h2 id="install-the-plugin-manually" tabindex="-1">Install the plugin manually <a class="header-anchor" href="#install-the-plugin-manually" aria-label="Permalink to &quot;Install the plugin manually&quot;">​</a></h2><p>Codex plugins are registered from a local marketplace snapshot, which the repository build produces. Build the repository first, then register that snapshot with the <code>codex</code> CLI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/seodduu/MCPLens.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MCPLens</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                          # also builds packages/extension/dist/codex-marketplace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> marketplace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/extension/dist/codex-marketplace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-lens@mcplens</span></span></code></pre></div><p><code>codex plugin list --json</code> should now list <code>mcp-lens@mcplens</code> under <code>installed</code>.</p><h2 id="what-it-collects" tabindex="-1">What it collects <a class="header-anchor" href="#what-it-collects" aria-label="Permalink to &quot;What it collects&quot;">​</a></h2><p>The plugin registers <code>SessionStart</code>, <code>PreToolUse</code>, <code>PostToolUse</code> and <code>Stop</code> hooks, using only its bundled hook runner. It never downloads a runtime, opens the MCP Lens database or uses the network, and it records only minimal MCP call metadata, atomically queued under <code>~/.mcplens/inbox</code>. Tool inputs, tool responses, prompt text and assistant-message bodies are not kept, and Codex&#39;s original session logs are left untouched.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Codex skips plugin-bundled hooks until their current hook-definition hash is reviewed and trusted. Open <code>/hooks</code> inside Codex, review the MCP Lens hook definition, and trust its current hash; do this again whenever the hash changes. Start a new Codex session after the hook state changes.</p><p>To stop collection, disable or remove the plugin registration; removing it uninstalls the plugin.</p>`,13)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
